import AppKit
import SwiftUI

/// Exchange logos; the logos are the official ones from the exchanges' own sites (embedded: no resource bundle needed).
struct ExchangeLogo: View {
    let exchange: String
    let size: CGFloat

    private static let binance: NSImage? = Data(base64Encoded: "").flatMap(NSImage.init(data:))

    private static let poloniex: NSImage? = Data(base64Encoded: "").flatMap(NSImage.init(data:))

    private static let bybit: NSImage? = Data(base64Encoded: "").flatMap(NSImage.init(data:))

    var body: some View {
        if exchange == "binance", let image = Self.binance {
            Image(nsImage: image).resizable().interpolation(.high).frame(width: size, height: size)
        } else if exchange == "bybit", let image = Self.bybit {
            Image(nsImage: image).resizable().interpolation(.high).frame(width: size, height: size)
                .clipShape(RoundedRectangle(cornerRadius: size * 0.22, style: .continuous))
        } else if exchange == "poloniex", let image = Self.poloniex {
            Image(nsImage: image).resizable().interpolation(.high).frame(width: size, height: size)
                .clipShape(RoundedRectangle(cornerRadius: size * 0.22, style: .continuous))
        } else {
            Image(systemName: "building.columns.fill").font(.system(size: size * 0.8)).foregroundStyle(.secondary).frame(width: size, height: size)
        }
    }
}
